    let mut score = post_residual as f64;

    // Strictly penalize small residual gaps that are unlikely to accept
    // future items, while making larger gaps progressively less costly.
    let dead_space_penalty = if post_residual == 0 {
        0.0
    } else if post_residual < 10 {
        85.0
    } else if post_residual < 20 {
        55.0
    } else if post_residual < 30 {
        32.0
    } else if post_residual < 40 {
        18.0
    } else if post_residual < 50 {
        9.0
    } else {
        3.0
    };
    score += dead_space_penalty;

    // Slightly favor preserving bins with substantially more usable room.
    let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (1.0 - utilization) * 12.0;

    // Penalize opening another bin when many bins are already active.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(6.0);
    score += pressure * 4.0;

    // When only one existing bin can fit, make a new bin comparatively
    // attractive if the placement would create severe dead space.
    if fitting_bins_count <= 1 {
        score += (post_residual as f64 / bin_capacity as f64) * 18.0;
    }

    // Mild lookahead: avoid consuming space needed by the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.4;
    }

    // Near the end of the stream, reduce the value of speculative preservation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Mean residual is a soft pressure signal: prefer fitting into bins
    // whose remaining space is below the current average when appropriate.
    score += ((mean_residual - post_residual as f64) * 0.08).max(-6.0).min(6.0);

    score
