    let dead_space_penalty = if post == 0.0 {
        0.0
    } else if next > 0.0 && post < next {
        (next - post) * 3.0
    } else {
        (post % 10.0) * 0.35
    };

    score += dead_space_penalty;

    // Prefer a tight fit, but avoid consuming the only bin that can hold a
    // relatively large upcoming item.
    let tightness = 1.0 - (post / capacity);
    score -= tightness * 2.0;

    // Harmonic capacity classes: exact and near-threshold residuals are
    // generally more useful than residues in awkward middle classes.
    let harmonic_class = (post as usize % 17) as f64;
    score += (harmonic_class / 17.0) * 0.8;
    if post % 5 == 0 {
        score -= 0.7;
