pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        1.0
    };

    let is_new_bin = bin_residual == bin_capacity;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let mean = mean_residual.max(0.0);

    if is_new_bin {
        score += 28.0;
        score += (mean - item).clamp(-25.0, 25.0) * 0.20;

        if next > 0.0 && item + next <= bin_capacity as f64 {
            score -= 24.0;
        }
        if fitting_bins_count == 0 {
            score -= 18.0;
        }
    } else {
        if next > 0.0 {
            let exact_match = (post_residual as f64 - next).abs();
            score += exact_match * 1.85;

            if post_residual == next {
                score -= 32.0;
            } else if post_residual > next && post_residual - next <= 8 {
                score -= 12.0;
            }
        } else {
            score += (post_residual as f64 - mean).abs() * 0.30;
        }

        let waste_ratio = if mean > 1.0 {
            ((post_residual as f64 - mean) / mean).clamp(-1.5, 1.5)
        } else {
            0.0
        };
        score += waste_ratio * 7.0;

        if post_residual < next && next > 0.0 {
