    let dead_space_threshold = 10.0_f64;
    let unusable_gap = (post_residual as f64).min(dead_space_threshold);
    score += 2.5 * unusable_gap;

    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += 18.0 + 0.8 * (next_item_size - post_residual) as f64;
    }

    if post_residual == 0 {
